// MarchingBlocks Paint for Unreal — THE MODE PANEL: the MarchingBlocks tool's right panel, compact.
//
// Shown in the mode toolbox while the MarchingBlocks mode is on. Its icons are MarchingBlocks' own
// (Resources/Icons, generated by DEV_TOOLS/generer_icones_greffons.gd), its groups those of the tool — aim,
// tool, brush, floor, selection — and its accent the tool's olive. It only shows what the current tool
// uses: the brush for Add · Dig · Select, Hollow for the Box, the selection when there is one, Paste when
// something is copied. Every setting stays on the actor (saved with the level); this panel only drives it.

#pragma once

#include "CoreMinimal.h"
#include "Toolkits/BaseToolkit.h"

class UMarchingBlocksEdMode;

class FMarchingBlocksModeToolkit : public FModeToolkit
{
public:
	virtual void Init(const TSharedPtr<IToolkitHost>& InitToolkitHost, TWeakObjectPtr<UEdMode> InOwningMode) override;
	virtual FName GetToolkitFName() const override { return FName("MarchingBlocksMode"); }
	virtual FText GetBaseToolkitName() const override;
	virtual TSharedPtr<SWidget> GetInlineContent() const override { return Panel; }

	/** The name of the Slate style that holds the icons, registered by the editor module. */
	static const FName StyleName;

private:
	TSharedRef<SWidget> BuildPanel();

	TWeakObjectPtr<UMarchingBlocksEdMode> Mode;
	TSharedPtr<SWidget> Panel;
};
